// Lab sheets for every experiment, and how the Lab sheets list is grouped.
// Each step is a heading (part and figure) and a numbered list of actions; the numbers are the step numbers in the
// course book (Electrical Testing (6) / (7)) or in the Emona manual named in `src`, so the sheet can be read next to
// the book. The text is our own wording. Arabic is simple Modern Standard Arabic.
// Wiring checks: `w` names the ready-made setup of that figure; the step checks the leads and probes that setup adds
// to the previous one. `c` / `p` add checks by hand (Term 1, and steps without a setup file).
import SETUPS from 'virtual:setups';

const fig = f => (f ? (/[–,]/.test(String(f)) ? { en: ` · Figures ${f}`, ar: ` · الأشكال ${f}` } : { en: ` · Figure ${f}`, ar: ` · الشكل ${f}` }) : { en: '', ar: '' });
const H = (part, f, adapted) => ({ en: `Part ${part}${fig(f).en}${adapted ? ' · adapted' : ''}`, ar: `الجزء ${part}${fig(f).ar}${adapted ? ' · مُعدَّل' : ''}` });
const A = (n, en, ar) => [n, en, ar];
const S = (head, acts, more = {}) => ({ head, acts, ...more });
const Q = (en, ar) => ({ en, ar });
const B = (n, f) => A(n, `Build the set-up in Figure ${f} (the connections are listed below).`, `نفِّذ التوصيل الموضّح في الشكل ${f} (التوصيلات مذكورة أسفل الخطوات).`);
const M = (n, f) => A(n, `Change the set-up as in Figure ${f} (the connections are listed below).`, `عدِّل التوصيل كما في الشكل ${f} (التوصيلات مذكورة أسفل الخطوات).`);
const T1 = n => ({ en: `Term 1 · Exp ${n}`, ar: `الترم الأول · التجربة ${n}` });
const T2 = n => ({ en: `Term 2 · Exp ${n}`, ar: `الترم الثاني · التجربة ${n}` });
const X = (en, ar) => ({ en: `Extra · ${en}`, ar: `إضافية · ${ar}` });

// Short phrases used in many sheets
const P = {
  both: A(null, 'Turn both channels on.', 'شغّل القناتين معاً.'),
  hp: n => A(n, 'Plug in the headphones (click the headphone socket on the BUFFER).', 'صِل السماعة (انقر على مقبس السماعة في BUFFER).'),
  bufMin: n => A(n, 'Turn the BUFFER gain fully anticlockwise.', 'أدِر GAIN في BUFFER عكس اتجاه عقارب الساعة حتى النهاية.'),
  talk: n => A(n, 'Talk, sing or hum while you watch the screen.', 'تكلّم أو غنِّ أو دندن وأنت تراقب الشاشة.'),
  tlpfGainMid: n => A(n, 'Set the TUNEABLE LPF GAIN to the middle.', 'اضبط GAIN في TUNEABLE LPF على المنتصف.'),
  tlpfGainMax: n => A(n, 'Turn the TUNEABLE LPF GAIN fully clockwise.', 'أدِر GAIN في TUNEABLE LPF مع اتجاه عقارب الساعة حتى النهاية.'),
  fcMax: n => A(n, 'Turn the TUNEABLE LPF fc fully clockwise.', 'أدِر fc في TUNEABLE LPF مع اتجاه عقارب الساعة حتى النهاية.'),
  fcMin: n => A(n, 'Turn the TUNEABLE LPF fc fully anticlockwise.', 'أدِر fc في TUNEABLE LPF عكس اتجاه عقارب الساعة حتى النهاية.'),
  extHf: n => A(n, 'Trigger on EXT with HF REJ coupling.', 'اجعل الزناد (Trigger) على EXT مع اقتران HF REJ.'),
  dc2: n => A(n, 'Set both channels to DC coupling.', 'اضبط اقتران القناتين على DC.'),
  seq00: n => A(n, 'Set the SEQUENCE GENERATOR switches to 00.', 'اضبط مفاتيح SEQUENCE GENERATOR على 00.'),
  tb: (n, v) => A(n, `Set the timebase to ${v}.`, `اضبط القاعدة الزمنية على ${v.replace(/ /g, '')}.`),
  twoCyc: (n, what = 'the message', whatAr = 'الرسالة') => A(n, `Set the timebase to show two cycles of ${what}.`, `اضبط القاعدة الزمنية لتظهر دورتان من ${whatAr}.`),
};

