// Wiring checks: the leads and probes a step's setup adds to what the student already has.
const key = (a, b) => (a < b ? a + '|' + b : b + '|' + a);
function resolve(sheet) {
  let have = new Set(), probes = {};
  for (const st of sheet.steps) {
    const c = [...(st.c || [])], p = { ...(st.p || {}) };
    if (st.w) {
      const s = SETUPS[st.w];
      if (!s) { console.warn('[sheets] missing setup', st.w); continue; }
      for (const l of s.leads) if (!have.has(key(l.a, l.b)) && !c.some(([a, b]) => key(a, b) === key(l.a, l.b))) c.push([l.a, l.b]);
      for (const [ch, v] of Object.entries(s.probes || {})) if (v && probes[ch] !== v && !(ch in p)) p[ch] = v;
      have = new Set(s.leads.map(l => key(l.a, l.b))); probes = { ...s.probes };
    }
    for (const [a, b] of c) have.add(key(a, b));
    Object.assign(probes, p);
    st.c = c.length ? c : undefined; st.p = Object.keys(p).length ? p : undefined;
  }
  return sheet;
}
export const SHEETS = RAW.map(resolve);

